const applications = $input.all();
const now = Date.now();

const reminders = [];

function getBerlinOffset(date) {
    const parts = new Intl.DateTimeFormat('en-US', {
        timeZone: 'Europe/Berlin',
        timeZoneName: 'longOffset'
    }).formatToParts(date);

    return parts.find(p => p.type === 'timeZoneName').value
        .replace('GMT', '');
}

for (const item of applications) {
    const app = item.json;

    if (!app.interview_date || !app.interview_time) {
        continue;
    }

    const localDateTime =
        `${app.interview_date}T${app.interview_time}`;

    // Initial estimate to determine Berlin's UTC offset
    let interviewDateTime = new Date(localDateTime + '+01:00');

    let offset = getBerlinOffset(interviewDateTime);

    interviewDateTime = new Date(localDateTime + offset);

    // Recheck offset in case the date crosses a DST boundary
    offset = getBerlinOffset(interviewDateTime);
    interviewDateTime = new Date(localDateTime + offset);

    const interviewTimestamp = interviewDateTime.getTime();

    if (!Number.isFinite(interviewTimestamp)) {
        continue;
    }

    const hoursUntilInterview =
        (interviewTimestamp - now) / 3600000;

    // 24-hour reminder: due between 24h and 23h55 before interview
    if (hoursUntilInterview <= 24 &&
        hoursUntilInterview > 23.9166667) {

        reminders.push({
            json: {
                ...app,
                reminder_type: '24H',
                hours_until_interview: hoursUntilInterview
            }
        });
    }

    // 1-hour reminder: due between 1h and 55 minutes before interview
    if (hoursUntilInterview <= 1 &&
        hoursUntilInterview > 0.9166667) {

        reminders.push({
            json: {
                ...app,
                reminder_type: '1H',
                hours_until_interview: hoursUntilInterview
            }
        });
    }
}

return reminders;

